"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["44761"],{81678(e){e.exports=JSON.parse('{"registro":{"codigo":"uniplus.selecao.processo_seletivo.etapa_fora_da_janela_da_fase","status":422,"titulo":"A etapa acontece inteira fora do per\xedodo da fase que a abriga; ajuste as datas da etapa para ficarem dentro do per\xedodo da fase"},"descricao":{"codigo":"uniplus.selecao.processo_seletivo.etapa_fora_da_janela_da_fase","requisitos":[],"oQueAconteceu":["O per\xedodo da etapa n\xe3o tem nenhum ponto em comum com o per\xedodo da fase do cronograma em\\nque ela acontece. H\xe1 dois casos, e a mensagem de detalhe diz qual ocorreu:","- a etapa **come\xe7a depois** de a fase ter terminado;\\n- a etapa **termina antes** de a fase ter come\xe7ado.","A etapa \xe9 parte da fase, ent\xe3o o per\xedodo dela cabe dentro do per\xedodo da fase. S\xf3 se\\ncompara o que os dois lados declararam, e a etapa que declara apenas um dos extremos\\nherda o outro da fase; por isso uma prova que s\xf3 diz quando come\xe7a pode cair fora de uma\\nfase que j\xe1 terminou. A recusa sai com **422**.","A regra vale ao definir as etapas, ao definir o cronograma e, como defesa, na\\npublica\xe7\xe3o e na retifica\xe7\xe3o em ato \xfanico.","Os casos em que a etapa come\xe7a antes da fase ou termina depois dela t\xeam c\xf3digos\\npr\xf3prios: [`etapa_comeca_antes_da_fase`](/erros/uniplus.selecao.processo_seletivo.etapa_comeca_antes_da_fase)\\ne [`etapa_termina_depois_da_fase`](/erros/uniplus.selecao.processo_seletivo.etapa_termina_depois_da_fase)."],"comoResolver":["Corrija as datas da etapa (`PUT /api/selecao/processos-seletivos/{id}/etapas`) para que\\ncaiam dentro da fase, ou ajuste o per\xedodo da fase\\n(`PUT /api/selecao/processos-seletivos/{id}/cronograma-fases`), conforme o edital.\\nRepita ent\xe3o a opera\xe7\xe3o recusada."],"ondeAparece":["Defini\xe7\xe3o de etapas do processo seletivo","Defini\xe7\xe3o do cronograma de fases do processo seletivo","Publica\xe7\xe3o inicial do processo seletivo","Retifica\xe7\xe3o em ato \xfanico"]},"modulo":{"id":"selecao","nome":"Sele\xe7\xe3o","assunto":"Processo seletivo"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"d146f1ba7c5762ff6b06be66801aa6e88c9be916"}}')}}]);